#[inline]
unsafe extern "C-unwind" fn reset_cdf_symbol_counter(
    mut cdf_ptr: *mut aom_cdf_prob,
    mut num_cdfs: core::ffi::c_int,
    mut cdf_stride: core::ffi::c_int,
    mut nsymbs: core::ffi::c_int,
) {
    let mut i: core::ffi::c_int = 0 as core::ffi::c_int;
    while i < num_cdfs {
        *cdf_ptr.offset((i * cdf_stride + nsymbs) as isize) = 0 as aom_cdf_prob;
        i += 1;
    }
}
