pub const PARTITION_BLOCK_SIZES: core::ffi::c_int = 5 as core::ffi::c_int;
pub const PARTITION_CONTEXTS: core::ffi::c_int = PARTITION_BLOCK_SIZES
    * PARTITION_PLOFFSET;

extern "C" {
    fn memcpy(
        __dest: *mut core::ffi::c_void,
        __src: *const core::ffi::c_void,
        __n: size_t,
    ) -> *mut core::ffi::c_void;
}
